    PrereqCheckRequest request = new PrereqCheckRequest("cluster");
    request.setRepositoryVersion("2.3.0.0");
    // nothing installed
    Assert.assertFalse(m_check.isApplicable(request));
    // YARN installed
    services.put("HDFS", Mockito.mock(Service.class));
